@startuml

class HBMS {
  + CalculateReliabilityRating(traveller: Traveller): float
}

class Traveller {
  + Name : string
  + CompanyName : string
  + Address : string
  + TravelPreferences : string[]
}

class SearchCriteria {
  + City : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + RoomType : string
  + MinimumRating : int
  + MaxCostPerNight : float
  + AdditionalPreferences : string[]
}

class PreliminaryBooking {
  + BookingIdentifier : string
  + Price : float
  + CityArea : string
  + HotelRating : int
  + KeyPreferences : string[]
}

class SpecialOffer {
  + Price : float
}

class Booking {
  + BookingIdentifier : string
  + CancellationDeadline : date
  + IsPrepaid : boolean
  + IsConfirmed : boolean
  + IsCancelled : boolean
}

class CreditCardInfo {
  + CardNumber : string
  + ExpiryDate : date
}

class Hotel {
  + Name : string
  + Rating : int
  + Address : string
}

class HotelChain {
  + Name : string
}

class RoomType {
  + Designation : string
}

class Availability {
  + IsFullyBooked : boolean
}

Traveller "1" -- "*" PreliminaryBooking
Traveller "1" -- "*" Booking
Traveller "1" -- "0..1" CreditCardInfo
Traveller "1" -- "0..*" SearchCriteria
PreliminaryBooking "1" -- "0..*" SpecialOffer
PreliminaryBooking "1" -- "1" SearchCriteria
Booking "1" -- "1" PreliminaryBooking
Booking "1" -- "1" Hotel
Booking "1" -- "1" CreditCardInfo
Hotel "0..1" -- "0..*" HotelChain
Hotel "1" -- "*" RoomType
Hotel "1" -- "*" Availability
RoomType "1" -- "0..*" Availability

@enduml

